H('249.d.5.C',3,"Support resources for small businesses include:","Small business development centers and SCORE mentors",["Gossip groups","Casinos","Arcades"],"These offer free help.")
H('249.d.5.C',4,"A new owner needing free advice on writing a business plan could contact:","A Small Business Development Center",["A rumor mill","A game store","A bakery"],"SBDCs counsel entrepreneurs.")
H('249.d.5.D',3,"A business with one owner who has unlimited personal liability is a:","Sole proprietorship",["Corporation","Limited liability company","Cooperative"],"Sole proprietors are personally liable.")
H('249.d.5.D',4,"An advantage of an LLC over a sole proprietorship is:","Limited personal liability",["No paperwork","Unlimited liability","No taxes ever"],"LLCs shield personal assets.")
H('249.d.6.A',3,"A virtual business must keep records of clients, work done, and:","Payments received",["Neighbors' names","Weather","Sports scores"],"Records support service and billing.")
H('249.d.6.A',4,"Business records are needed to prove:","What services were provided and what was paid",["Nothing","Only the owner's age","Gossip"],"Proof protects both sides.")
H('249.d.6.B',3,"Storing client contact details securely in a database is:","Maintaining customer records",["Deleting data","Ignoring clients","Printing flyers"],"Records should be organized and safe.")
H('249.d.6.B',4,"Customer records should be:","Kept confidential and up to date",["Shared publicly","Left outdated","Posted online"],"Confidentiality and accuracy matter.")
H('249.d.7.A',3,"Reviewing monthly income and expense records to see trends is:","Monitoring internal records",["Guessing","Hiding data","Printing ads"],"Internal data guides decisions.")
H('249.d.7.A',4,"If internal records show one service earns most of the revenue, the owner might:","Focus more effort on that service",["Drop all services","Ignore it","Hide it"],"Records reveal strengths.")
H('249.d.7.B',3,"Studying competitors, laws, and technology trends is an:","Environment scan",["Audit","Billing","Hiring"],"Scans find outside factors.")
H('249.d.7.B',4,"Learning that more clients now prefer video meetings is a result of:","An environment scan",["An invoice","A tax return","A payroll run"],"Scanning detects trends.")
H('249.d.8.A',3,"Listing the people and tools needed for a project is part of:","Initiating a project",["Closing a project","Billing a client","Marketing a service"],"Initiation identifies resources.")
H('249.d.8.A',4,"The first step of a project is to:","Define its goal and needed resources",["Close it","Skip planning","Ignore costs"],"Define before doing.")
H('249.d.8.B',3,"A project plan lists tasks, deadlines, and:","Responsibilities",["Songs","Recipes","Weather"],"Plans assign ownership.")
H('249.d.8.B',4,"Putting deadlines in a project plan helps a team:","Stay on schedule",["Delay work","Hide tasks","Avoid roles"],"Deadlines guide pacing.")
H('249.d.8.C',3,"Performing the work in the project plan is:","Executing the project",["Closing the project","Planning only","Marketing"],"Execution means doing.")
H('249.d.8.C',4,"During execution, a virtual office owner should:","Communicate progress to the client",["Disappear","Stop answering","Delay updates"],"Communication keeps trust.")
H('249.d.8.D',3,"Comparing progress to the plan and coordinating with other teams is:","Monitoring and controlling",["Closing","Initiating","Marketing"],"Monitoring checks progress.")
H('249.d.8.D',4,"If a task depends on another team's delayed work, the owner should:","Coordinate and adjust the schedule",["Ignore the delay","Cancel the project","Hide the issue"],"Coordination reduces conflicts.")
H('249.d.8.E',3,"Delivering final work and gathering client feedback is:","Closing a project",["Initiating","Planning","Delaying"],"Closure confirms completion.")
H('249.d.8.E',4,"At project close, the owner should:","Review what worked and file project records",["Delete files immediately","Ignore feedback","Skip invoicing"],"Closure captures lessons.")

# ---- 250 Human Resources Management
H('250.d.1.A',3,"The department that handles hiring, training, pay, and employee relations is:","Human resources",["Shipping","Marketing","Accounting only"],"HR manages people.")
H('250.d.1.A',4,"The term human resources refers to:","The people who work in an organization and the function managing them",["Only computers","Only buildings","Only inventory"],"Employees are the resource.")
H('250.d.1.B',3,"Recruiting, selection, training, and compensation are basic:","Human resources functions",["Shipping tasks","Sales tactics","Plumbing jobs"],"These are core HR functions.")
H('250.d.1.B',4,"Placing applicants in the right job after testing and interviewing is the function of:","Selection",["Recruiting","Compensation","Termination"],"Selection chooses among applicants.")
H('250.d.1.C',3,"A contemporary issue facing HR managers is:","Managing a multigenerational and global workforce",["Using only typewriters","Eliminating all employees","Avoiding laws"],"Workforces are more diverse.")
H('250.d.1.C',4,"Remote work and rapid technology change are:","Contemporary HR issues",["Ancient history","Irrelevant topics","Banned practices"],"Modern workplaces change quickly.")
H('250.d.1.D',3,"A strategy HR uses to keep employees is offering:","Flexible schedules and career growth",["Pay cuts","Longer shifts only","No feedback"],"Flexibility aids retention.")
H('250.d.1.D',4,"Using online platforms for recruiting is an example of:","A contemporary HR strategy",["An outdated method","A banned practice","A pay cut"],"Technology supports HR.")
H('250.d.1.E',3,"As more older workers delay retirement, HR must plan for:","A wider age range on teams",["Younger employees only","Fewer benefits","No training"],"Demographics shape policy.")
H('250.d.1.E',4,"A growing share of women and minorities in the workforce requires HR to promote:","Inclusive policies and fair treatment",["Identical treatment of rules","Secrecy","Exclusion"],"Diversity needs inclusion.")
H('250.d.1.F',3,"A basic responsibility of an HR manager is:","Staffing the organization",["Welding","Driving trucks","Cooking meals"],"HR staffs organizations.")
H('250.d.1.F',4,"HR managers are also responsible for:","Keeping employment records and complying with laws",["Setting stock prices","Painting offices","Delivering mail"],"Compliance and records.")
H('250.d.1.G',3,"An effective HR manager needs strong communication and:","Ethics and knowledge of employment law",["No skills","Secrecy only","Poor judgment"],"Core competencies.")
H('250.d.1.G',4,"Which competency lets an HR manager handle disputes fairly?","Conflict resolution",["Ignoring","Guessing","Delay"],"Mediation skills matter.")
H('250.d.1.H',3,"Strategic HR planning begins by:","Forecasting the organization's future staffing needs",["Ignoring goals","Waiting for turnover","Firing staff"],"Plans align with business goals.")
H('250.d.1.H',4,"A company plans to double in size. HR strategic planning should include:","Recruiting and training plans for new hires",["Cutting training","Freezing hiring","Closing HR"],"Growth needs staffing.")
H('250.d.2.A',3,"The Equal Pay Act requires employers to pay men and women:","Equal pay for equal work",["Different pay","Higher pay for men","No pay"],"The Equal Pay Act bans sex-based pay gaps.")
H('250.d.2.A',4,"Title VII of the Civil Rights Act prohibits job discrimination based on race, color, religion, sex, or:","National origin",["Shoe size","Height only","Hobbies"],"National origin is protected.")
H('250.d.2.B',3,"A federal law that requires employers to give unpaid leave for family and medical reasons is the:","Family and Medical Leave Act",["Clean Air Act","Sherman Act","Tax Reform Act"],"FMLA covers job-protected leave.")
H('250.d.2.B',4,"The Age Discrimination in Employment Act protects workers aged:","40 and older",["16 and younger","Any age","Only 70 and older"],"The ADEA protects workers 40+.")
H('250.d.2.C',3,"Written HR policies help an organization by:","Treating employees consistently and fairly",["Creating confusion","Hiding rules","Avoiding laws"],"Policies guide behavior.")
H('250.d.2.C',4,"A strong anti-harassment policy should include:","A clear reporting procedure and protection from retaliation",["Secret rules","Punishing reporters","No training"],"Clear procedures protect employees.")
H('250.d.2.D',3,"A contemporary social issue facing HR is:","Pay equity and workplace inclusion",["Typewriter repair","Ancient trade routes","Candle supplies"],"Social issues shape HR.")
H('250.d.2.D',4,"A political issue affecting HR is changes in:","Minimum wage and leave laws",["Fashion trends","Weather","Sports schedules"],"Laws change employer duties.")
H('250.d.2.E',3,"To comply with Equal Employment Opportunity rules, employers must keep:","Accurate records and post required notices",["Hidden files","No records","Changing rules"],"Compliance requires documentation.")
H('250.d.2.E',4,"If a worker files a discrimination charge, the employer should:","Cooperate with the investigation and avoid retaliation",["Fire the worker","Destroy records","Ignore it"],"Retaliation is illegal.")
H('250.d.2.F',3,"Studying the tasks, duties, and skills a job requires is:","Job analysis",["Job loss","Job fair","Job title only"],"Job analysis defines the job.")
H('250.d.2.F',4,"Employee involvement programs let workers:","Share ideas and take part in decisions",["Be ignored","Work alone","Skip training"],"Involvement improves engagement.")
H('250.d.2.G',3,"A job description lists duties, qualifications, and:","Reporting relationships",["Songs","Weather","Menu"],"It defines the role.")
H('250.d.2.G',4,"A well-written job description helps because it:","Tells applicants and employees what is expected",["Hides duties","Removes pay","Avoids laws"],"Clarity guides hiring.")
H('250.d.2.H',3,"To research a current equal employment case, a student should use:","Court and news reports from reliable online sources",["Rumors","Guesses","Anonymous posts"],"Reliable sources matter.")
H('250.d.2.H',4,"The federal agency that enforces many job discrimination laws is the:","Equal Employment Opportunity Commission",["Federal Reserve","FDA","Postal Service"],"The EEOC enforces these laws.")
H('250.d.3.A',3,"Recruiting externally includes posting jobs on:","Online job boards and at career fairs",["Only the break room","Nowhere","Employees' lockers"],"External recruiting reaches outside candidates.")
H('250.d.3.A',4,"A drawback of external recruiting compared with internal is that it can:","Cost more and take longer",["Cost less always","Be instant","Avoid interviews"],"External searches are costlier.")
H('250.d.3.B',3,"Filling an opening by promoting a current employee is:","Internal recruiting",["External recruiting","Layoff","Outsourcing"],"Promotion fills from within.")
H('250.d.3.B',4,"An advantage of internal recruiting is that it:","Boosts morale and uses known performers",["Always costs more","Ignores talent","Hurts morale"],"Promotions motivate staff.")
H('250.d.3.C',3,"To build a diverse pool of applicants, a company can:","Advertise through varied outlets and community groups",["Post only once","Use one source","Avoid outreach"],"Wide outreach finds more talent.")
H('250.d.3.C',4,"Partnering with schools and organizations serving different communities helps a firm:","Reach a wider range of qualified candidates",["Narrow its pool","Avoid hiring","Lower standards"],"Outreach broadens candidates.")
H('250.d.3.D',3,"EEOC guidelines require that hiring tests and criteria be:","Job-related and not discriminatory",["Random","Secret","Biased"],"Criteria must relate to the job.")
H('250.d.3.D',4,"An interview question about a candidate's religion is generally:","Inappropriate and unlawful to base a decision on",["Required","Encouraged","Neutral"],"Protected topics should be avoided.")
H('250.d.4.A',3,"Comparing an applicant's skills with the job description is:","Matching the applicant to the job",["Ignoring skills","Firing staff","Printing forms"],"Match uses job analysis.")
H('250.d.4.A',4,"A job specification lists the:","Qualifications a person needs to do the job",["Office hours only","Pay of the boss","Parking rules"],"Specs list required traits.")
H('250.d.4.B',3,"A test that measures typing speed for a clerk's job is a:","Skills test",["Personality quiz unrelated to work","Weather report","Trivia game"],"Skills tests check job abilities.")
H('250.d.4.B',4,"A pre-employment drug screen is typically used to:","Verify the applicant can safely perform the job",["Discriminate","Reject all applicants","Replace interviews"],"Safety-sensitive jobs may require screens.")
H('250.d.4.C',3,"When conducting a background check, an employer should consider:","Legal limits and applicant consent",["Gossip","Rumors","Nothing"],"Checks must follow laws.")
H('250.d.4.C',4,"Before running a credit or background check, the Fair Credit Reporting Act generally requires the employer to:","Get the applicant's written permission",["Skip notice","Ignore consent","Post it online"],"Consent is required.")
H('250.d.4.D',3,"A structured interview helps reduce bias by:","Asking every candidate the same job-related questions",["Asking random questions","Chatting casually","Skipping notes"],"Consistency improves fairness.")
H('250.d.4.D',4,"An interviewer should end an interview by:","Explaining next steps and thanking the candidate",["Walking away","Making promises","Ignoring questions"],"Closure is professional.")
H('250.d.5.A',3,"Before designing training, HR should analyze:","Which skills employees lack",["The color of the walls","Parking","Lunch menus"],"Needs analysis comes first.")
H('250.d.5.A',4,"A needs assessment for training can use:","Surveys, performance data, and interviews",["Guesswork","Rumors","Luck"],"Data identifies gaps.")
H('250.d.5.B',3,"Designing a training program starts with setting:","Learning objectives",["Menu items","Ad slogans","Logos"],"Objectives guide content.")
H('250.d.5.B',4,"A good training design includes:","Clear goals, activities, and ways to measure results",["Random topics","No goals","Endless lectures"],"Design links goals to assessment.")
H('250.d.5.C',3,"Implementing a training program includes scheduling, trainers, and:","Materials and facilities",["Rumors","Excuses","Delays"],"Logistics support delivery.")
H('250.d.5.C',4,"Rolling out training in small sessions to avoid disrupting work is:","A practical implementation choice",["Poor planning","A violation","A layoff"],"Scheduling balances work.")
H('250.d.5.D',3,"Measuring whether trainees learned and used new skills is:","Evaluating the training program",["Hiring","Recruiting","Firing"],"Evaluation shows results.")
H('250.d.5.D',4,"A common way to evaluate training is to compare:","Performance before and after training",["Weather","Logos","Prices"],"Comparisons show improvement.")
H('250.d.5.E',3,"New employee orientation should cover company policies, safety rules, and:","Job expectations and introductions",["Rumors","Gossip","Privileged data"],"Orientation sets expectations.")
H('250.d.5.E',4,"Orientation helps new hires by:","Reducing anxiety and speeding adjustment",["Raising turnover","Hiding rules","Cutting pay"],"Good starts improve retention.")
H('250.d.5.F',3,"Learning job tasks while working under a skilled coworker's guidance is:","On-the-job training",["Classroom lecture only","A written test","Orientation only"],"OJT is hands-on.")
H('250.d.5.F',4,"Besides on-the-job training, skills training can include:","Apprenticeships and simulations",["Gossip","Rumors","Waiting"],"Many formats exist.")
H('250.d.5.G',3,"New hires must be trained in proper Equal Employment Opportunity practices so they:","Treat coworkers and customers fairly and lawfully",["Ignore rules","Avoid training","Hide complaints"],"Training prevents violations.")
H('250.d.5.G',4,"Training on harassment prevention reduces the company's:","Legal risk and workplace conflict",["Training budget only","Customer base","Product line"],"Prevention protects everyone.")
H('250.d.6.A',3,"Employees often need extra training to learn new technology and:","Update outdated skills",["Forget skills","Avoid growth","Skip safety"],"Skills change over time.")
H('250.d.6.A',4,"A company adopts new software. Employees will likely need:","Additional training on the system",["Pay cuts","Layoffs only","No support"],"New tools require training.")
H('250.d.6.B',3,"An appraisal program must comply with laws by being:","Job-related and applied fairly",["Biased","Secret","Random"],"Appraisals must be valid.")
H('250.d.6.B',4,"A fair appraisal form measures:","Performance on actual job duties",["Appearance only","Age","Family status"],"Criteria must relate to work.")
H('250.d.6.C',3,"Employees may be evaluated by supervisors and also by:","Peers and customers",["Strangers only","No one","Competitors"],"Multiple raters add perspective.")
H('250.d.6.C',4,"A 360-degree review collects feedback from:","Supervisors, peers, and subordinates",["Only the boss","Only the employee","Only customers"],"360 feedback is multi-source.")
H('250.d.7.A',3,"Compensation should reflect the job's value and also meet the organization's:","Budget and goals",["Whims","Rumors","Excuses"],"Pay must be affordable and aligned.")
H('250.d.7.A',4,"A company wants to attract skilled workers within a limited budget. Compensation must balance:","Competitiveness and cost",["Nothing","Secrecy","Delay"],"Pay is a tradeoff.")
H('250.d.7.B',3,"Factors that influence a pay system include the labor market, job worth, and:","The organization's ability to pay",["The employee's hobbies","Weather","Sports scores"],"Several factors set pay.")
H('250.d.7.B',4,"A shortage of skilled workers in a field usually pushes wages:","Up",["Down","To zero","Nowhere"],"Scarcity raises pay.")
H('250.d.7.C',3,"A salesperson who earns a percentage of each sale is paid by:","Commission",["Piece rate","Hourly wage","Salary only"],"Commission ties pay to sales.")
H('250.d.7.C',4,"A factory worker paid $2 per unit produced is paid by:","Piece rate",["Commission","Salary","Bonus only"],"Piece-rate pays per unit.")
H('250.d.7.D',3,"A wage and salary survey helps an employer:","Compare its pay with what others pay",["Hide pay","Set prices","Close offices"],"Surveys benchmark pay.")
H('250.d.7.D',4,"To perform a wage and salary survey, HR typically:","Collects pay data for similar jobs from comparable employers",["Guesses","Asks only competitors' fans","Skips job titles"],"Benchmarking uses comparable data.")
H('250.d.7.E',3,"Pay that increases as an employee gains new skills is:","Competence-based pay",["Commission only","Piece rate","Overtime"],"Skills drive raises.")
H('250.d.7.E',4,"A benefit of competence-based pay is that it:","Encourages employees to learn more skills",["Discourages growth","Removes standards","Lowers all pay"],"Skills are rewarded.")
H('250.d.7.F',3,"The Fair Labor Standards Act sets federal rules on minimum wage and:","Overtime pay",["Vacation length","Dress code","Parking"],"FLSA covers minimum wage and overtime.")
H('250.d.7.F',4,"Under the FLSA, nonexempt employees working over 40 hours a week generally receive overtime of:","One and a half times their regular rate",["Half their rate","Double only","No extra pay"],"Overtime is time and a half.")
H('250.d.7.G',3,"A contemporary compensation issue is:","Pay equity across genders and groups",["Candle prices","Typewriter ribbon","Telegrams"],"Equity is a current concern.")
H('250.d.7.G',4,"Pay transparency laws require some employers to:","Disclose salary ranges for jobs",["Hide pay","Cut pay","Avoid posting jobs"],"Transparency reduces gaps.")
H('250.d.7.H',3,"A one-time payment for strong performance is a:","Bonus",["Salary","Tax","Fine"],"Bonuses reward results.")
H('250.d.7.H',4,"Sharing company profits with employees is called:","Profit sharing",["Piece rate","Overtime","Commission only"],"Profit sharing distributes earnings.")
H('250.d.7.I',3,"Executive pay becomes an ethical issue when it is:","Much higher than company performance justifies",["Fairly linked to results","Modest","Disclosed"],"Excess raises fairness concerns.")
H('250.d.7.I',4,"Large executive bonuses during layoffs may harm a company's:","Public relations and employee morale",["Taxes only","Nothing","Product line"],"Optics affect trust.")
H('250.d.7.J',3,"To research executive compensation cases, a student can use:","Company filings and credible news sites",["Rumors","Gossip","Guesses"],"Public filings are reliable.")
H('250.d.7.J',4,"A public company reports executive pay in its:","Proxy statement filed with the SEC",["Newsletter only","Lunch menu","Parking permit"],"Proxy statements disclose pay.")
H('250.d.8.A',3,"Federal law requires employers to pay Social Security and Medicare taxes under the:","Federal Insurance Contributions Act",["Clean Water Act","Sherman Act","Tariff Act"],"FICA funds these programs.")
H('250.d.8.A',4,"Employers must also pay into state and federal:","Unemployment insurance",["Gym memberships","Vacation funds","Parking funds"],"Unemployment insurance is mandatory.")
H('250.d.8.B',3,"Health insurance, paid time off, and retirement plans are:","Discretionary benefits",["Mandated benefits","Fines","Taxes"],"Employers choose to offer them.")
H('250.d.8.B',4,"A 401(k) plan is a common:","Retirement benefit",["Health claim","Tax form","Vacation policy"],"401(k)s help employees save.")
H('250.d.8.C',3,"Employee assistance programs and tuition reimbursement are:","Ancillary services",["Taxes","Fines","Penalties"],"They are extra services.")
H('250.d.8.C',4,"Offering on-site child care or wellness programs is an example of:","Ancillary services",["Mandated benefits","Wages","Overtime"],"Extras support employees.")
H('250.d.9.A',3,"The Occupational Safety and Health Act requires employers to provide:","A workplace free from recognized hazards",["Unlimited pay","Free lunch","Short shifts"],"OSHA sets safety duties.")
H('250.d.9.A',4,"The agency that enforces workplace safety laws is:","OSHA",["The EEOC","The SEC","The FDA"],"OSHA enforces safety standards.")
H('250.d.9.B',3,"Right-to-know laws give employees information about:","Hazardous chemicals they work with",["Coworkers' pay","Company profits","Hiring plans"],"Hazard communication protects workers.")
H('250.d.9.B',4,"Safety Data Sheets are used to inform workers about:","The hazards of chemicals and how to handle them",["Pay rates","Vacation plans","Parking"],"SDSs communicate hazards.")
H('250.d.9.C',3,"A safety awareness program might include posters, training, and:","Regular safety drills and meetings",["Penalties only","Secret rules","No communication"],"Programs build safe habits.")
H('250.d.9.C',4,"To promote safety awareness, a manager can:","Recognize safe behavior and share near-miss lessons",["Hide accidents","Ignore reports","Punish reporting"],"Open reporting improves safety.")
H('250.d.9.D',3,"Enforcing workplace safety rules is necessary to:","Prevent injuries and avoid fines",["Slow work","Raise costs only","Annoy staff"],"Enforcement protects people.")
H('250.d.9.D',4,"A worker repeatedly ignores required protective gear. The manager should:","Apply consistent corrective action",["Ignore it","Reward it","Hide the issue"],"Consistent enforcement keeps rules credible.")
H('250.d.9.E',3,"After a workplace accident, the employer must:","Record and investigate the incident",["Hide it","Ignore it","Delay indefinitely"],"Investigation prevents recurrence.")
H('250.d.9.E',4,"The goal of an accident investigation is to find:","The root cause so it can be prevented",["Someone to blame","A reason to delay","An excuse"],"Root cause analysis prevents repeats.")
H('250.d.9.F',3,"A way to prevent workplace violence is:","Clear policies, training, and a reporting process",["Ignoring threats","Hiding incidents","Removing security"],"Prevention requires policy and training.")
H('250.d.9.F',4,"An employee reports a threat from a coworker. HR should:","Take it seriously and investigate promptly",["Dismiss it","Wait a year","Ignore it"],"Threats need prompt action.")
H('250.d.9.G',3,"Employers can help employees manage workplace stress by offering:","Counseling resources and reasonable workloads",["Longer shifts","No breaks","More pressure"],"Support reduces stress.")
H('250.d.9.G',4,"Chronic workplace stress can lead to:","Lower productivity and higher absenteeism",["Better health","Lower turnover","Less conflict"],"Stress harms performance.")
H('250.d.9.H',3,"To research a workplace violence case, a student should use:","Credible news and legal sources",["Rumors","Gossip","Guesses"],"Reliable sources matter.")
H('250.d.9.H',4,"When analyzing a violence case, a student should look for:","What warning signs were missed and how to prevent recurrence",["Only blame","Only gossip","Nothing"],"Analysis focuses on prevention.")
H('250.d.10.A',3,"Employee rights, such as fair pay and safe conditions, are balanced by employer:","Responsibilities and legitimate business needs",["Fears","Hobbies","Jokes"],"Rights and duties coexist.")
H('250.d.10.A',4,"An employer's responsibility includes:","Providing a safe workplace and following wage laws",["Avoiding all rules","Ignoring complaints","Cutting safety"],"Employers have legal duties.")
H('250.d.10.B',3,"Progressive discipline usually starts with:","A verbal warning",["Termination","A raise","A promotion"],"Discipline escalates in steps.")
H('250.d.10.B',4,"Documenting each disciplinary step is important because it:","Provides a record if the decision is challenged",["Hides actions","Lowers morale","Replaces training"],"Documentation protects fairness.")
H('250.d.10.C',3,"Before discharging an employee, HR should:","Review documentation and follow policy and law",["Act on impulse","Skip records","Ignore rules"],"Proper process avoids claims.")
H('250.d.10.C',4,"An exit interview helps the organization:","Learn why employees leave",["Hide issues","Avoid feedback","Keep secrets"],"Exit data reveals problems.")
H('250.d.10.D',3,"Using mediation or arbitration instead of court to settle a workplace dispute is:","Alternative Dispute Resolution",["Litigation","Strike","Lockout"],"ADR avoids court.")
H('250.d.10.D',4,"A benefit of Alternative Dispute Resolution is that it is usually:","Faster and less costly than court",["Slower","More public","Always binding on no one"],"ADR saves time and money.")
H('250.d.10.E',3,"The federal law that protects workers' right to organize and bargain collectively is the:","National Labor Relations Act",["Clean Air Act","Sherman Act","Tariff Act"],"The Wagner Act (NLRA) protects organizing.")
H('250.d.10.E',4,"The Taft-Hartley Act is best known for:","Restricting certain union and strike practices",["Banning all unions","Creating Social Security","Setting minimum wage"],"It amended the Wagner Act.")
H('250.d.10.F',3,"Employees may join a union to seek better pay, benefits, and:","Working conditions",["Less pay","Fewer rights","More hazards"],"Unions bargain for improvements.")
H('250.d.10.F',4,"Workers often unionize because they want:","A collective voice with management",["Isolation","Lower pay","Less safety"],"Collective bargaining gives workers leverage.")
H('250.d.10.G',3,"During a union organizing drive, an employer may NOT:","Threaten or fire workers for supporting the union",["Share facts","Answer questions","Post legal notices"],"Retaliation is an unfair labor practice.")
H('250.d.10.G',4,"During unionization, an employer may lawfully:","Share factual information about the company's position",["Spy on meetings","Threaten layoffs","Promise rewards for voting no"],"Truthful communication is allowed.")
H('250.d.10.H',3,"A union's local chapter is run by:","Elected officers and stewards",["Random strangers","The employer","The government"],"Locals are member-led.")
H('250.d.10.H',4,"A union steward typically:","Represents members in grievances",["Hires managers","Sets stock prices","Owns the company"],"Stewards support members.")
H('250.d.10.I',3,"The AFL-CIO is a:","Federation of national and international unions",["Federal agency","Corporation","Court"],"It unites many unions.")
H('250.d.10.I',4,"A national union is made up of many:","Local unions",["Companies","Courts","Banks"],"Locals affiliate with nationals.")
H('250.d.10.J',3,"Negotiations between a union and an employer over wages, hours, and conditions are:","Collective bargaining",["Arbitration only","A lockout","A boycott"],"Bargaining produces the contract.")
H('250.d.10.J',4,"The written agreement resulting from bargaining is the:","Collective bargaining agreement",["Resume","Invoice","Business plan"],"The CBA sets terms.")
H('250.d.10.K',3,"A formal process for resolving a worker's complaint under a union contract is a:","Grievance procedure",["Hiring plan","Marketing plan","Pay cut"],"Grievances follow steps.")
H('250.d.10.K',4,"A typical grievance begins with:","The employee and steward talking to the supervisor",["A strike","A lawsuit","A lockout"],"First step is informal discussion.")
